import csv
import io
import re
from typing import List, Dict, Any, Optional, Tuple

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_data_line(s: str) -> bool:
        if not s:
            return False
        return bool(re.match(r'^\s*\d{1,2}/\d{1,2}/\d{4},', s))

    def is_header_line(s: str) -> bool:
        if not s:
            return False
        u = s.strip().upper()
        return u.startswith("DATE,TIME,") or u == "DATE,TIME,QTY,PRODUCTID,PRICE,PRODUCTTYPE,\"PRODUCTDESCRIPTION\",\"URL\",COMMENTS"

    start_idx = None
    for i, line in enumerate(lines):
        if is_data_line(line) or is_header_line(line):
            start_idx = i
            break
    if start_idx is None:
        start_idx = 0

    relevant = "\n".join(lines[start_idx:]).strip("\n")
    if not relevant:
        return {"columns": [], "rows": []}

    reader = csv.reader(io.StringIO(relevant), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
    rows = []
    for row in reader:
        if not row:
            continue
        if len(row) == 1 and not row[0].strip():
            continue
        rows.append([str(v) for v in row])

    header_idx = None
    for i, row in enumerate(rows):
        joined = ",".join([c.strip() for c in row]).upper()
        if joined.startswith("DATE,TIME,") and "PRODUCTID" in joined and "PRODUCTTYPE" in joined:
            header_idx = i
            break

    if header_idx is not None:
        header = rows[header_idx]
        data_rows = rows[header_idx + 1 :]
        if len(header) < 9:
            header = header + [""] * (9 - len(header))
        elif len(header) > 9:
            header = header[:9]
        columns = [c.strip() for c in header]
        normalized_rows = []
        for row in data_rows:
            if len(row) < 9:
                row = row + [""] * (9 - len(row))
            elif len(row) > 9:
                row = row[:9]
            normalized_rows.append([str(v) for v in row])
        return {"columns": columns, "rows": normalized_rows}

    columns = ["DATE", "TIME", "Qty", "PRODUCTID", "Price", "ProductType", "ProductDescription", "URL", "Comments"]
    normalized_rows = []
    for row in rows:
        if len(row) < 9:
            row = row + [""] * (9 - len(row))
        elif len(row) > 9:
            row = row[:9]
        normalized_rows.append([str(v) for v in row])
    return {"columns": columns, "rows": normalized_rows}
